import os
from openai import OpenAI

def answer_with_context(question: str, context: str) -> str:
    """
    Calls a hosted LLM (OpenAI's GPT-3.5 Turbo) to answer a question using provided context.
    """
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
    )

    response = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            {"role": "system", "content": f"You are a helpful assistant. Use the following context to answer the user's question.\n\nContext: {context}"},
            {"role": "user", "content": question}
        ],
        max_tokens=200,
        temperature=0.2,
    )
    return response.choices[0].message.content.strip()

import os
from openai import OpenAI
from typing import Iterator

def stream_completion(prompt: str) -> Iterator[str]:
    """
    Streams partial output tokens from a hosted LLM (OpenAI's GPT-3.5 Turbo).
    """
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
    )

    stream = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            {"role": "user", "content": prompt}
        ],
        stream=True,
    )

    for chunk in stream:
        if chunk.choices[0].delta.content is not None:
            yield chunk.choices[0].delta.content
